import{_ as t,H as r,c as a,b as n,a2 as o,K as i}from"./chunks/framework.BEqfOpL-.js";const w=JSON.parse(`{"title":"Related Shows","description":"See the shows that recommend yours, the shows your own pages recommend, and the audience connections between them. These are useful leads for cross-promotion and competitor research; they aren't measured listener referrals.","frontmatter":{},"headers":[],"relativePath":"features/related-podcasts.md","filePath":"features/related-podcasts.md"}`),h={name:"features/related-podcasts.md"};function c(l,e,d,p,u,m){const s=r("HelpWalkthrough");return n(),a("div",null,[e[0]||(e[0]=o('<h1 id="related-shows" tabindex="-1">Related Shows <a class="header-anchor" href="#related-shows" aria-label="Permalink to &quot;Related Shows&quot;">​</a></h1><p>See the shows that recommend yours, the shows your own pages recommend, and the audience connections between them. These are useful leads for cross-promotion and competitor research; they aren&#39;t measured listener referrals.</p><p><strong>To access:</strong> <strong>Measure → Recommendations</strong> in the sidebar, or the <strong>Related Shows</strong> tab in <strong>Plan → Competition</strong>. Both open the same page. Older guides called this Related Podcasts or Referral Podcasts; existing links still open this guide.</p><h2 id="read-your-podcast-s-neighbourhood" tabindex="-1">Read your podcast&#39;s neighbourhood <a class="header-anchor" href="#read-your-podcast-s-neighbourhood" aria-label="Permalink to &quot;Read your podcast&#39;s neighbourhood&quot;">​</a></h2><p>The map places your show among linked podcasts. Closer shows have stronger links: they may recommend you back or connect through several sources. Bigger covers indicate more popular shows. Faded shows represent past connections.</p><p><strong>Arrows point to the recommended show:</strong></p><ul><li>Toward your show: that show recommends you.</li><li>Away from your show: your platform page or feed recommends that show.</li><li>Arrowheads both ways: the recommendation is mutual.</li><li>Grey arrows: a past connection.</li></ul><ol><li>Read the arrow legend, then use <strong>Spotify</strong>, <strong>Apple Podcasts</strong>, <strong>Podroll</strong>, or <strong>Past connections</strong> to focus the map.</li><li>Zoom in to inspect a connection; <strong>Reset view</strong> restores the map. Hover a cover for its source and direction. On touch screens, tap once for its detail.</li><li>Compare the incoming lists below the map with <strong>Past connections</strong> and the shows on your own platform pages or RSS podroll.</li></ol>',8)),i(s,{src:"/walkthroughs/related-directions.webp",poster:"/images/referrals.webp",alt:"Read recommendation directions, filter past connections, zoom and reset the neighbourhood map, then compare incoming, past and outgoing show lists",duration:40650,autoplay:"",loop:"",sample:""}),e[1]||(e[1]=o('<p>The lists provide full counts and source details, including when your browser cannot display the map. A desktop click on a map cover opens that show&#39;s platform page; a second tap on the selected cover does the same on touch screens.</p><h2 id="check-the-source-and-direction" tabindex="-1">Check the source and direction <a class="header-anchor" href="#check-the-source-and-direction" aria-label="Permalink to &quot;Check the source and direction&quot;">​</a></h2><p><strong>Apple Podcasts — Listeners Also Liked</strong> and <strong>Spotify — You Might Also Like</strong> show where platforms recommend you on other podcast pages.</p><p>For Apple Podcasts, a card can also show your position on that show&#39;s <strong>Listeners Also Liked</strong> list (for example &quot;You&#39;re #3 on its Apple list&quot;), and <strong>Shown on your page</strong> can show where Apple places a show on yours (&quot;#1 on Apple&#39;s list&quot;). Shows with a position come first, best position first. Apple shows the first 3 shows without scrolling, so positions 1–3 are highlighted. Positions are still being collected: a card without one hasn&#39;t been re-checked yet, and that doesn&#39;t mean it ranks low.</p><p><strong>YouTube Music — Suggested podcasts</strong> lists the shows YouTube Music suggests on your show&#39;s page, in YouTube Music&#39;s order, and the shows whose page suggests yours, with your position on their list. Shows marked <strong>From the same channel</strong> belong to your own YouTube channel: they are the publisher&#39;s catalogue, not competitors. &quot;YouTube Music shows no suggestions for this show yet&quot; is common for smaller shows and is not an error; &quot;Not checked on YouTube Music yet&quot; means the first check hasn&#39;t run. YouTube Music isn&#39;t drawn on the map yet.</p><p><strong>Podroll — Creator recommendations</strong> shows recommendations creators publish in RSS feeds. A podroll link is a creator&#39;s choice, rather than a platform&#39;s automatic suggestion.</p><p>Past connections are kept separate from current ones. <strong>Shown on your page</strong> is the other direction: the shows your own listing or feed recommends. Seeing a show there does not mean it recommends you back.</p><p>If collection hasn&#39;t finished or there are no known connections, read the page&#39;s status message. No observed connection isn&#39;t evidence that nobody listens to both shows.</p><h2 id="choose-useful-partners" tabindex="-1">Choose useful partners <a class="header-anchor" href="#choose-useful-partners" aria-label="Permalink to &quot;Choose useful partners&quot;">​</a></h2><ol><li>Find a current incoming or mutual connection relevant to your audience.</li><li>Open the show on its platform or RSS feed and check its content.</li><li>Use <strong>Track</strong> if you want it in <a href="/features/competitive-analysis.html">Competitive Analysis</a>. <strong>Tracking</strong> marks shows already in your list; your competitor allowance applies.</li><li>Approach a suitable host about a guest swap or promotion with a specific idea for both audiences.</li></ol><p>These links indicate a connection between shows, not clicks, downloads, or a guaranteed audience transfer.</p><h2 id="draft-podcasts" tabindex="-1">Draft podcasts <a class="header-anchor" href="#draft-podcasts" aria-label="Permalink to &quot;Draft podcasts&quot;">​</a></h2><p>For an eligible draft, Related Shows offers potential peers based on its selected keywords and saved competitors. These are positioning references, not live recommendations of an unpublished show. See <a href="/getting-started/pre-launch-planning.html">Pre-launch Planning</a>.</p>',13))])}const f=t(h,[["render",c]]);export{w as __pageData,f as default};
